exercises.starter_code:
fn modify(_p: &mut i32) {}

fn main() {
    let mut num = 5;
}

exercises.solution:
fn modify(p: &mut i32) {
    *p *= 2;
}

fn main() {
    let mut num = 5;
    modify(&mut num);
    println!("{}", num);
}

