exercises.starter_code:
fn swap(_a: &mut i32, _b: &mut i32) {}

fn main() {
    let mut x = 5;
    let mut y = 10;
}

exercises.solution:
fn swap(a: &mut i32, b: &mut i32) {
    std::mem::swap(a, b);
}

fn main() {
    let mut x = 5;
    let mut y = 10;
    swap(&mut x, &mut y);
    println!("{} {}", x, y);
}
